{"code": "var { chromium } = await import('playwright');
var browser = await chromium.launch();
var page = await browser.newPage();
var errors = [];
page.on('console', m => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
await page.goto('http://localhost:48123/demo.html', { waitUntil: 'networkidle' });
var boardInfo = await page.evaluate(() => {
  const out = [];
  for (const id of ['board-1','board-2','board-3','board-4','board-5']) {
    const wrap = document.getElementById(id);
    const board = wrap ? wrap.querySelector('cg-board') : null;
    out.push({ id, hasWrap: !!wrap, hasBoard: !!board, squares: board ? board.querySelectorAll('cg-square').length : 0, pieces: board ? board.querySelectorAll('cg-piece').length : 0 });
  }
  return out;
});
nodeRepl.write('boards: ' + JSON.stringify(boardInfo, null, 1));
nodeRepl.write('console errors: ' + JSON.stringify(errors));
var before = await page.evaluate(() => document.querySelector('#board-1 > cg-board').getBoundingClientRect().width);
await page.evaluate(() => { document.querySelector('.chessground').style.cssText = 'width:300px;height:300px'; });
await page.waitForTimeout(500);
var after = await page.evaluate(() => ({ board: document.querySelector('#board-1 > cg-board').getBoundingClientRect().width, wrap: document.querySelector('#board-1').getBoundingClientRect().width }));
nodeRepl.write('board-1 width before resize: ' + before + '  after: ' + JSON.stringify(after));
await page.screenshot({ path: 'D:/dev/ab-tasks/chessground-qwen-med-r2/demo-after-resize.png' });
await browser.close();", "title": "Load demo, verify boards, resize", "timeout_ms": 90000}

