const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();
  await page.goto('http://localhost:48123/demo.html', { waitUntil: 'networkidle' });
  const info = await page.evaluate(() => {
    const wrap = document.querySelector('#board-1');
    const container = wrap.querySelector('cg-container');
    const board = wrap.querySelector('cg-board');
    const cs = el => {
      const s = getComputedStyle(el);
      return { backgroundImage: s.backgroundImage.slice(0, 60), backgroundColor: s.backgroundColor };
    };
    return { wrap: cs(wrap), container: cs(container), board: cs(board) };
